changeSet.sql:
INSERT INTO system_settings (created_at, updated_at, setting_key, setting_value, value_type, description, active, deleted, version)
SELECT now(), now(), 'http-client.platform.connect-timeout-millis', '3000', 'NUMBER', 'Connect timeout (ms) - general-purpose platform HTTP client.', true, false, 0
WHERE NOT EXISTS (SELECT 1 FROM system_settings WHERE setting_key = 'http-client.platform.connect-timeout-millis');

